void shouldFailToInsertDuplicatePetNameForSameOwner() {
	Optional<Owner> optionalOwner = this.owners.findById(1);
	assertThat(optionalOwner).isPresent();
	Owner owner = optionalOwner.get();

	Pet pet1 = new Pet();
	pet1.setName("DuplicatePetName");
